@TestOn('browser')
library;

import 'dart:convert';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:idb_shim/idb_browser.dart';
import 'package:grumpy_skies/features/fun/meme/storage/meme_indexeddb_backend.dart';
import 'package:grumpy_skies/features/roasts/content/roast_pack_repository.dart';

class _CountingAssets extends CachingAssetBundle {
  int loads = 0;
  @override
  Future<ByteData> load(String key) async {
    loads++;
    return ByteData.sublistView(Uint8List.fromList(utf8.encode(_fixture)));
  }
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  test('real browser IndexedDB restart serves bundle without loading its asset',
      () async {
    final database =
        'roast_browser_test_${DateTime.now().microsecondsSinceEpoch}';
    final backend =
        IndexedDbMemeBackend(idbFactoryNative, databaseName: database);
    final cache = DurableRoastPackCache(backend);
    final firstAssets = _CountingAssets();
    final first = RoastPackRepository(assetBundle: firstAssets, cache: cache);
    final bundle = await first.loadBundledPack();
    expect(firstAssets.loads, 1);
    final restartedAssets = _CountingAssets();
    final restarted = RoastPackRepository(
        assetBundle: restartedAssets,
        cache: DurableRoastPackCache(
            IndexedDbMemeBackend(idbFactoryNative, databaseName: database)));
    expect((await restarted.loadBundledPack()).packVersion, bundle.packVersion);
    expect(restartedAssets.loads, 0);
    // Evicted metadata cannot make a fresh repository fail: rehydrate asset.
    await backend.remove('metadata', 'roast_pack_index_v2');
    final evictedAssets = _CountingAssets();
    final evicted =
        RoastPackRepository(assetBundle: evictedAssets, cache: cache);
    expect(
        (await evicted.loadBundledPack()).roasts.length, bundle.roasts.length);
    expect(evictedAssets.loads, 1);
  });
}

